import json

def transform_final(grid):
    if len(grid) != 15:
        return grid

    sep_idx = None
    for i in range(len(grid)):
        if all(c == 5 for c in grid[i]):
            sep_idx = i
            break

    if sep_idx is None:
        return grid

    top_colors = set()
    for row in grid[0:sep_idx]:
        for c in row:
            if c != 0: top_colors.add(c)
    bottom_colors = set()
    for row in grid[sep_idx+1:]:
        for c in row:
            if c != 0: bottom_colors.add(c)

    top_max = max(top_colors) if top_colors else 0
    bottom_max = max(bottom_colors) if bottom_colors else 0

    # Find 3x3 single-color bboxes
    top_bboxes = []
    for r in range(len(grid)-2):
        for c in range(15-2):
            vals = []
            for dr in range(3):
                for dc in range(3):
                    vals.append(grid[r+dr][c+dc])
            non_zero = set(v for v in vals if v != 0)
            if len(non_zero) == 1:
                top_bboxes.append((top_max, 1, vals))

    bottom_bboxes = []
    for r in range(len(grid)-sep_idx-1-2):
        for c in range(15-2):
            vals = []
            for dr in range(3):
                for dc in range(3):
                    vals.append(grid[sep_idx+1+r+dr][c+dc])
            non_zero = set(v for v in vals if v != 0)
            if len(non_zero) == 1:
                bottom_bboxes.append((bottom_max, vals))

    top_bboxes.sort(key=lambda x: -x[1])
    bottom_bboxes.sort(key=lambda x: -x[1])

    output = [[0]*15 for _ in range(9)]

    # TOP: Vertical flip of the largest bbox
    if top_bboxes:
        vals, = top_bboxes[0][2]
        # Flip vertically: swap row 0 and row 2
        flipped = vals[6:9] + vals[3:6] + vals[0:3]
        for dr in range(3):
