        vals = bottom_bboxes[0][1]
        for dr in range(3):
            for dc in range(3):
                if vals[dr*3+dc] != 0:
                    output[5+dr][5+dc] = bottom_max

    return output, top_bboxes[:5] if top_bboxes else [], bottom_bboxes[:5] if bottom_bboxes else []

